    h, w = len(grid), len(grid[0])
    bg = grid[0][0]
    out = [row[:] for row in grid]

    # Locate the contiguous vertical color-key column.
    candidates = []
    for c in range(w - 1):
        r = 0
        while r < h:
            if grid[r][c] == bg:
                r += 1
                continue
            start = r
            while r < h and grid[r][c] != bg:
                r += 1
            candidates.append((r - start, c, start, r))
    length, kc, ks, ke = max(candidates)
    key = {grid[r][kc]: grid[r][kc + 1] for r in range(ks, ke)}

    # Gather connected L-trominoes by their original colors.
    seen = set()
    objects = {}
    for r in range(h):
        for c in range(w):
            if (r, c) in seen or grid[r][c] == bg:
                continue
            color = grid[r][c]
            todo = [(r, c)]
            seen.add((r, c))
            part = []
            while todo:
                x, y = todo.pop()
                part.append((x, y))
                for dx, dy in ((1, 0), (-1, 0), (0, 1), (0, -1)):
                    xx, yy = x + dx, y + dy
                    if 0 <= xx < h and 0 <= yy < w and (xx, yy) not in seen and grid[xx][yy] == color:
                        seen.add((xx, yy))
                        todo.append((xx, yy))
            if len(part) == 3:
                objects.setdefault(color, []).append(part)

    boxes = []
    for color, pair in objects.items():
        if len(pair) == 2:
            points = pair[0] + pair[1]
            box = (min(x for x, y in points), max(x for x, y in points),
                   min(y for x, y in points), max(y for x, y in points), key[color])
            boxes.append(box)

    # Paint outer rectangles first so nested rectangles remain visible.
    boxes.sort(key=lambda b: (b[1] - b[0]) * (b[3] - b[2]), reverse=True)
    for top, bottom, left, right, color in boxes:
        for r in range(top, bottom + 1):
            for c in range(left, right + 1):
                if grid[r][c] == bg:
                    out[r][c] = color
    return out
